with base as (select id, device_code, reading_ts, humidity, status_bits, firmware, cast(reading_ts as date) as reading_ts_day from device_readings where reading_ts >= timestamp '2025-09-01 04:00:00'), enriched as (select *, sum(status_bits) over w_recent as running_sum_status_bits, count(status_bits) over w_recent as running_count_status_bits, avg(status_bits) over w_recent as running_avg_status_bits, min(status_bits) over w_recent as running_min_status_bits from base window w_recent as (partition by device_code order by status_bits, id rows between unbounded preceding and current row)), enriched_device_readings as (select id, status_bits, running_avg_status_bits, sum(status_bits) over w_ordered as status_bits_sum_30m, round(humidity / sum(humidity) over (partition by device_code), 4) as humidity_share, ntile(3) over (partition by device_code order by humidity, id) as humidity_bucket from enriched window w_ordered as (partition by device_code order by cast(reading_ts as bigint) range between 1800 preceding and current row)), scored as (select id, status_bits, running_avg_status_bits, humidity_share, avg(humidity_share) over w_ordered as humidity_share_avg_2_prior, last_value(humidity_bucket) ignore nulls over (order by humidity_bucket, id rows between unbounded preceding and current row) as last_known_humidity_bucket, cume_dist() over (order by status_bits desc) as status_bits_cume_dist, avg(running_avg_status_bits) over (order by status_bits_sum_30m, id rows between 6 preceding and 1 preceding) as running_avg_status_bits_avg_6_prior from enriched_device_readings where humidity_share >= 0.2 window w_ordered as (order by running_avg_status_bits, id rows between 2 preceding and 1 preceding)) select case when running_avg_status_bits_avg_6_prior >= 11 then 'PREMIUM' else 'STANDARD' end as running_avg_status_bits_avg_6_prior_tier, percentile_approx(humidity_share_avg_2_prior, array(0.25, 0.5, 0.75)) as humidity_share_avg_2_prior_quartiles, count(distinct id) as distinct_ids, round(avg(humidity_share), 2) as avg_humidity_share from scored group by running_avg_status_bits_avg_6_prior_tier order by distinct_ids desc nulls first
